// TH15 synthetic catalog aliases used by this card (type 23/24 of type 0..43).
// Reuses the existing modern slots; source="th15". Base radius 7, colors 0..7.
const TH15_BIG_STAR_R: int = 720;
const TH15_BIG_STAR_L: int = 736;

// TH15 v1.00b st05.ecl::MainSub04 (1538-1548) wave of four GirlD02.
// Source t0 = MainSub04 entry; card frame0 starts the phase, +120 opening buffer.
// Pair A at source t=2: (-92,-48) unmirrored, (164,-48) enmCreateM.
// Pair B at source t=162: (-182,-48) unmirrored, (74,-48) enmCreateM.
// Creation x uses stage FINAL (origin) + input; enmCreateM only sets the child mirror bit.
const TIME_LIMIT: int = 1730;
const OPENING_BUFFER: int = 120;

xformdef BULLET_RAMP {
    // Source GirlD02_at2 975: etEx type0x200000 VELTIME a=120, r=8, angle retained.
    // Linear scalar speed 2 -> 8 over 120 ticks. Birth ANIM is omitted by policy;
    // its -4*initial-speed retreat is applied at spawn through sh_dist.
    step_speed(8fx, 120 + 65536 * EASE_LINEAR);
}

// GirlD02_at2 (956-1026): aimed fan bursts, own shooter per enemy.
async sub girl_fire() {
    var rank: int = global(GVAR_RANK);
    // 976 diffI($A,2,32,32,32): Easy runs 2 rounds, the other ranks 32.
    var rounds: int = 32;
    // 964-971: spread 0.349066rad (20deg) on E/N/H, 0.261799rad (15deg) on L.
    var spread: angle = 20deg;
    // 980-988 / 1002-1010: first burst 6 ways (L 10), second burst 5 ways (L 9).
    var n_first: int = 6;
    var n_second: int = 5;
    // 991-999 / 1013-1021: wait 20 on E/N, 15 on H, 10 on L.
    var gap: int = 20;
    if rank == 0 { rounds = 2; }
    if rank == 2 { gap = 15; }
    if rank == 3 {
        spread = 15deg;
        n_first = 10;
        n_second = 9;
        gap = 10;
    }
    sh_reset(0);
    sh_aim(0, 1);                 // 960 etAim(0,0): aimed fan
    sh_ring(0, 0);
    sh_speed(0, 2fx, 0fx);        // 973 etSpeed(0,2,1) with one layer
    sh_dist(0, -8fx);             // 974 ANIM a=1: position -= 4*velocity, speed 2
    sh_xform(0, BULLET_RAMP);
    for i in 0..rounds {
        // 979-1000: shape23/color3 aimed fan, then the source wait.
        sh_sprite(0, TH15_BIG_STAR_R, 3);
        sh_count(0, n_first, 1);
        sh_angle(0, 0deg, spread);
        sh_fire(0);
        wait(gap);
        // 1001-1022: shape24/color6, then the same wait.
        sh_sprite(0, TH15_BIG_STAR_L, 6);
        sh_count(0, n_second, 1);
        sh_angle(0, 0deg, spread);
        sh_fire(0);
        wait(gap);
    }
}

// GirlD02 (925-936): animation/drops omitted; GirlD02_at loops forever.
async sub girl_main(mirror: int) {
    set_invuln(65535);
    set_hitbox(8fx);              // 941 setHitbox(16,16): ordinary circle r=8
    set_hurtbox(12fx);            // 940 setHurtbox(24,24): ordinary circle r=12
    // 942-947: moveVel(pi/2,3); moveVelTime(60,mode1,1.3744467,0); then 120 later
    // moveVelTime(60,mode0,0.19634955,1). Mirrored movement reflects angle as 180deg-theta.
    var turn1: angle = 14336 as angle;  // 78.75deg = 1.3744467rad
    var turn2: angle = 2048 as angle;   // 11.25deg = 0.19634955rad
    if mirror != 0 {
        turn1 = 18432 as angle;         // 180deg - 78.75deg
        turn2 = 30720 as angle;         // 180deg - 11.25deg
    }
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, turn1, 0fx, EASE_QUAD_IN);
    wait(60);
    spawn girl_fire();                  // 945 @GirlD02_at2() async
    wait(120);
    move_vel(60, turn2, 1fx, EASE_LINEAR);
    loop { wait(1000); }                // 949-952 wait loop keeps the enemy alive
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wait(2);                            // 1541
    _ = spawn_enemy(-92fx, -48fx, 600, 0, 0, 0, girl_main(0));
    _ = spawn_enemy(164fx, -48fx, 600, 0, 0, 0, girl_main(1));
    wait(160);                          // 1544
    _ = spawn_enemy(-182fx, -48fx, 600, 0, 0, 0, girl_main(0));
    _ = spawn_enemy(74fx, -48fx, 600, 0, 0, 0, girl_main(1));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
